Evaluate Integer RPN Stack.good:
def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token not in ("+", "-", "*", "/"):
            stack.append(int(token)); continue
        b, a = stack.pop(), stack.pop()
        if token == "+": v = a + b
        elif token == "-": v = a - b
        elif token == "*": v = a * b
        else: v = (abs(a) // abs(b)) * (-1 if (a < 0) != (b < 0) else 1)
        stack.append(v)
    return stack[0]

Stable Topological Schedule.good:
def schedule(nodes, edges):
    import heapq
    adjacent = {n: [] for n in nodes}
    degrees = {n: 0 for n in nodes}
    for a, b in edges:
        adjacent[a].append(b); degrees[b] += 1
    ready = [n for n in nodes if degrees[n] == 0]
    heapq.heapify(ready); result = []
    while ready:
        n = heapq.heappop(ready); result.append(n)
        for b in adjacent[n]:
            degrees[b] -= 1
            if degrees[b] == 0: heapq.heappush(ready, b)
    return result if len(result) == len(nodes) else None

LRU Operation Replay.good:
def replay_lru(capacity, operations):
    from collections import OrderedDict
    cache = OrderedDict(); result = []
    for op in operations:
        key = op[1]
        if op[0] == "get":
            result.append(cache.get(key))
            if key in cache: cache.move_to_end(key)
        else:
            cache[key] = op[2]; cache.move_to_end(key)
            if len(cache) > capacity: cache.popitem(last=False)
    return result

